function literalPrefix(pattern) { return pattern.slice(0, Math.max(0, pattern.search(/[?*]/) === -1 ? pattern.length : pattern.search(/[?*]/))); }
function resourceOverlap(a, b) {
  const ag = /[?*]/.test(a); const bg = /[?*]/.test(b);
  if (!ag && !bg) return a === b;
